INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (1, "2030/12/31 15:00:00", "みそぎ", 3, 0.0, 0, 0, 1, 0, 0, "ミソギ（リトルリリカル）", 0, 0, 0, 180801, 0, 0, 120501, 465, 0, 120501, "2015/04/01 15:00:00", 0, 0, "");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (1, "2030/12/31 15:00:00", "きょうか", 3, 0.0, 0, 0, 1, 0, 0, "キョウカ（リトルリリカル）", 0, 0, 0, 180801, 0, 0, 120601, 465, 0, 120601, "2015/04/01 15:00:00", 0, 0, "");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/01/31 11:59:59", "しぇふぃ", 3, 1.84, 1, 0, 1, 0, 1, "シェフィ（ニューイヤー）", 0, 22, 0, 0, 120701, 0, 120701, 283, 4, 120701, "2026/01/15 12:00:00", 120701, 450, "【物理】前衛で、雪花舞う晴れ空をゆく新春氷竜少女。\nＵＢで顕現させる氷竜の牙で味方への強化スキルを高め\n自身の範囲攻撃技と共に苛烈な攻勢で敵陣を凍滅する。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "るか", 1, 1.3, 2, 0, 1, 0, 1, "ルカ（ニューイヤー）", 0, 22, 0, 0, 120801, 0, 120801, 193, 4, 120801, "2023/10/16 15:00:00", 120801, 450, "【物理】前衛で雪月花の舞を納める新春の姉御。\n攻撃を当てる度に増加する【剣の刻印】でＵＢとスキルの\n威力を上昇させ、目にも止まらぬ斬撃で敵を圧倒する。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/01/31 11:59:59", "いりや", 3, 1.425, 12, 0, 1, 0, 2, "イリヤ（ニューイヤー）", 0, 38, 0, 0, 120901, 0, 120901, 424, 3, 120901, "2026/01/15 12:00:00", 120901, 450, "【魔法】中衛で自らの血を代償に力を振るう新春吸血鬼。\n自身のＨＰを消費して放つ強力なスキルと、敵からＴＰを\n吸収するスキルを自在に操り、目の前の敵を撃滅する。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/02/09 11:59:59", "ぺこりーぬ", 3, 2.25, 1, 0, 1, 0, 1, "ペコリーヌ（オーバーロード）", 0, 41, 0, 0, 121001, 0, 121001, 164, 5, 121001, "2026/01/31 12:00:00", 121001, 450, "【物理】前衛で、仲間との絆を力に変え戦う腹ペコ王女。\n敵のＨＰ状態で永続の物理攻撃力上昇と、短時間の特大\n攻撃力上昇＆自己ＴＰ回復を使い分け戦況を一変させる。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/02/09 11:59:59", "きゃる", 3, 2.07, 1, 0, 1, 0, 2, "キャル（オーバーロード）", 0, 42, 0, 0, 121101, 0, 121101, 588, 7, 121101, "2026/01/31 12:00:00", 121101, 450, "【魔法】中衛で仲間との絆を力に変え戦うツンデレ猫娘。\n敵を妨害するスキルと、ＵＢで敵全体を恐慌状態にし既に\n恐慌状態の敵のＴＰをダウンさせ、全戦場を掌握する。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "らびりすた", 1, 1.55, 6, 0, 1, 0, 1, "ラビリスタ（オーバーロード）", 0, 40, 0, 0, 121201, 0, 121201, 260, 4, 121201, "2023/11/16 15:00:00", 121201, 450, "【物理】前衛で世界の理をすべて見つめる『迷宮女王』。\n味方を攻撃面で強化し、継続ＨＰ回復を全体に付与する\nスキルで戦線を整え、自身も圧倒的な力で敵を殲滅する。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "くるみ", 3, 1.9, 3, 0, 0, 0, 1, "クルミ（ステージ）", 0, 3, 0, 0, 121301, 0, 121301, 731, 3, 121301, "2022/03/03 19:00:00", 121301, 450, "【物理】後衛で、皆のため意を決し奮起する小さな女優。\n残りＨＰが多いほど物理攻撃力がアップし、物理攻撃無効\nバリアのスキルやＨＰ・ＴＰ継続回復で味方を支援する。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "みさき", 3, 2.27, 15, 0, 0, 0, 2, "ミサキ（ステージ）", 0, 7, 0, 0, 121401, 0, 121401, 742, 7, 121401, "2022/03/15 15:00:00", 121401, 450, "【魔法】後衛で後ろの味方を強化する魔法少女の看板娘。\n後衛の味方をバリアとＴＰ継続回復で支援し、自分の魔法\n攻撃力に応じ強化される攻撃力アップスキルで鼓舞する。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/04/15 11:59:59", "あゆみ", 3, 2.0, 12, 0, 1, 0, 1, "アユミ（怪盗）", 0, 6, 0, 0, 121501, 0, 121501, 590, 6, 121501, "2026/03/31 12:00:00", 121501, 450, "【物理】中衛で、闇夜に身を潜める神出鬼没の怪盗少女。\n敵の目の前から姿を消す隠密スキルや、遠くの敵に対する\nＴＰダウンスキルを駆使して、敵陣後方から瓦解させる。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "いのり", 3, 1.425, 17, 0, 0, 0, 1, "イノリ（怪盗）", 0, 3, 0, 0, 121601, 0, 121601, 292, 3, 121601, "2022/04/15 15:00:00", 121601, 450, "【物理】前衛で闇に紛れ会心の一撃を放つ怪盗ドラゴン。\n隠密効果中、ダメージが大アップし必ずクリティカルする\nＵＢとスキルを駆使し安定したダメージを敵に叩き込む。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (1, "2030/12/31 15:00:00", "あきの", 3, 0.0, 0, 0, 1, 0, 0, "アキノ（アキノ＆サレン）", 0, 0, 0, 180901, 0, 0, 121701, 421, 0, 121701, "2015/04/01 15:00:00", 0, 0, "");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (1, "2030/12/31 15:00:00", "されん", 3, 0.0, 0, 0, 1, 0, 0, "サレン（アキノ＆サレン）", 0, 0, 0, 180901, 0, 0, 121801, 421, 0, 121801, "2015/04/01 15:00:00", 0, 0, "");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "あんな", 3, 2.125, 12, 0, 0, 0, 2, "アンナ（パイレーツ）", 0, 5, 0, 0, 121901, 0, 121901, 293, 5, 121901, "2022/05/15 15:00:00", 121901, 450, "【魔法】前衛で己を鼓舞し高めた魔力を放つ蒼海の冥姫。\n発動の度、攻撃力とクリティカル時ダメージが上昇する\nＵＢと自己犠牲を払う強力な範囲攻撃技で敵を撃滅する。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "しのぶ", 3, 1.425, 14, 0, 0, 0, 1, "シノブ（パイレーツ）", 0, 3, 0, 0, 122001, 0, 122001, 380, 3, 122001, "2022/05/03 19:00:00", 122001, 450, "【物理】中衛で、彷徨える魂を解き放つ海星の霊能少女。\n攻撃の際、付与する【霊錨の刻印】を駆使し、ダメージ量\nアップのスキルと防御力ダウンのＵＢで敵を浄滅へ導く。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "あおい", 1, 1.97, 9, 0, 1, 0, 1, "アオイ（キャンプ）", 0, 35, 0, 0, 122101, 0, 122101, 731, 35, 122101, "2024/04/18 15:00:00", 122101, 450, "【物理】後衛で百千の矢を放つ、ぼっちの山籠りエルフ。\n物理魔法無効バリアで耐え凌ぎ、敵全体への射撃と自分の\n間合いに入った敵への強力な弓雨の追撃で掃討する。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "ゆかり", 3, 1.84, 8, 0, 0, 0, 1, "ユカリ（キャンプ）", 0, 4, 0, 0, 122201, 0, 122201, 419, 4, 122201, "2022/05/31 12:00:00", 122201, 450, "【物理】中衛で最高の一杯を自然と共に愉しむ元聖騎士。\n【至福のひと時】が増えるほどに、味方の物理攻撃力や\nクリティカル時のダメージを強力に強化し、勝利を掴む。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "うぁんぴぃ", 3, 1.425, 0, 0, 0, 0, 2, "ヴァンピィ", 0, 43, 0, 0, 122301, 0, 122301, 564, 43, 122301, "2022/06/15 15:00:00", 122301, 450, "【魔法】中衛で、幼き竜と共に歩むさいきょーの吸血姫。\n味方全体の強化と、敵のＴＰを吸収するスキルで力を蓄え\nＵＢ発動後ベスと共闘し防御ダウンと強撃で攻勢に出る。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "ひより", 1, 2.42, 8, 0, 1, 0, 1, "ヒヨリ（サマー）", 0, 1, 0, 0, 122401, 0, 122401, 264, 1, 122401, "2024/06/17 15:00:00", 122401, 450, "【物理】前衛で皆にエールを送り鼓舞する真夏の元気娘。\n味方のＨＰを継続回復し行動速度アップの他、味方の数に\n応じてクリティカル強化と攻撃力を引き上げ勝利に導く。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/08/31 11:59:59", "れい", 3, 1.965, 0, 0, 1, 0, 1, "レイ（サマー）", 0, 4, 0, 0, 122501, 0, 122501, 250, 4, 122501, "2026/08/26 12:00:00", 122501, 450, "【物理】前衛で水刃の加護を纏い水面を駆ける渚の剣士。\nクリティカル時のダメージを底上げしＵＢ発動の度、纏う\n【水刃の加護】で全スキルダメージを上げ、敵陣を穿つ。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "ゆい", 3, 2.27, 0, 0, 0, 0, 2, "ユイ（サマー）", 0, 7, 0, 0, 122601, 0, 122601, 554, 7, 122601, "2022/07/15 15:00:00", 122601, 450, "【魔法】中衛で、魔法キャラを補助する夜凪の魔法士。\n累積する攻撃強化スキルとＴＰ回復、物魔両面の無効\nバリアや継続ＨＰ回復で攻守共に味方を支え勝利へ導く。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "きょうか", 3, 1.92, 0, 0, 0, 0, 2, "キョウカ（サマー）", 0, 7, 0, 0, 122701, 0, 122701, 812, 7, 122701, "2022/08/15 15:00:00", 122701, 450, "【魔法】後衛で、難しい魔法の練習に励む海辺の優等生。\nランダムな敵に当たるスキルの威力は攻撃の際に付与する\n【バタフライシール】で増幅し、防御力もダウンさせる。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "みそぎ", 1, 2.295, 0, 0, 1, 0, 1, "ミソギ（サマー）", 0, 1, 0, 0, 122801, 0, 122801, 237, 1, 122801, "2024/07/16 15:00:00", 122801, 450, "【物理】前衛で敵後方に花火を仕掛ける夜涼みの悪戯娘。\n敵の最前衛をスタンで足止めしつつ、最後衛を中心とした\nＵＢで狭範囲の敵を引き寄せ、ＴＰダウンで攻勢を阻む。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/08/31 11:59:59", "みみ", 3, 2.25, 0, 0, 1, 0, 1, "ミミ（サマー）", 0, 5, 0, 0, 122901, 0, 122901, 361, 5, 122901, "2026/08/26 12:00:00", 122901, 450, "【物理】中衛で巨大バルーンと跳ね回る夏色うさぎっこ。\nＵＢやスキルで全てのマルチターゲットに追加ダメージを\n与え、自己強化と防御力ダウンで強敵のブレイクを狙う。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/08/26 11:59:59", "あめす", 3, 2.27, 0, 0, 1, 0, 2, "アメス", 0, 44, 0, 0, 123001, 0, 123001, 746, 44, 123001, "2026/08/23 12:00:00", 123001, 450, "【魔法】後衛で、新たな姿で騎士の冒険を支える妖精。\nダメージカットや防御力アップ、無効バリアで味方を護り\nバリアを起点とする攻撃力とＴＰの支援で攻勢に転ずる。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "まほ", 3, 1.795, 0, 0, 0, 0, 2, "マホ（エクスプローラー）", 0, 7, 0, 0, 123101, 0, 123101, 793, 7, 123101, "2022/09/03 19:00:00", 123101, 450, "【魔法】後衛でぬいぐるみ達と大冒険に挑むマホ隊員。\n味方に付与する【ふわふわウール】は被ダメージ時に消費\nされＴＰを回復し、一気呵成の反撃で活路を切り拓く。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "あやね", 3, 1.425, 0, 0, 0, 0, 1, "アヤネ（エクスプローラー）", 0, 3, 0, 0, 123201, 0, 123201, 256, 3, 123201, "2022/09/15 15:00:00", 123201, 450, "【物理】前衛で、相棒と困難を越え猛進するアヤネ隊員。\n群る敵を二つの範囲攻撃で一気に捉え、周囲の味方の物理\n攻撃力とクリティカルアップで冒険を阻む壁を打ち崩す。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/02/28 11:59:59", "ねあ", 3, 1.62, 0, 0, 1, 0, 1, "ネア", 0, 0, 0, 0, 123301, 0, 123301, 350, 1, 123301, "2026/02/15 12:00:00", 123301, 450, "【物理】中衛で粘液を振りまくキイロいスライムギャル。\nスキルで敵全体の物理攻撃能力やＴＰ上昇を低下させ、\nＵＢでスライム化し全敵を攻撃しつつ無敵ボディを得る。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "じゅん", 3, 0.0, 0, 0, 0, 0, 0, "ジュン（キャンプ）", 0, 5, 0, 0, 0, 0, 123401, 0, 5, 123401, "2015/04/01 15:00:00", 0, 0, "");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "りん", 1, 2.34, 0, 0, 1, 0, 1, "リン（ハロウィン）", 0, 6, 0, 0, 123501, 0, 123501, 583, 6, 123501, "2024/09/17 15:00:00", 123501, 450, "【物理】中衛で敵を悪戯で翻弄する恐怖のキョンシー娘。\n最も魔法攻撃力が高い敵に急襲を仕掛け、ＴＰ減少や魔法\n攻撃力ダウン、スタン等の妨害スキルで機先を制する。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2025/11/30 11:59:59", "とも", 3, 1.965, 0, 0, 1, 0, 1, "トモ（ハロウィン）", 0, 4, 0, 0, 123601, 0, 123601, 262, 4, 123601, "2025/11/14 15:00:00", 123601, 450, "【物理】前衛で、同志と力を合わせ共に戦う夜廻り剣士。\n自分と物理攻撃力が最も高い味方１キャラの攻撃力を大幅\nに上昇させ、目にもとまらぬ剣技で不届き者を成敗する。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "ななか", 3, 2.07, 0, 0, 0, 0, 2, "ナナカ（ハロウィン）", 0, 21, 0, 0, 123701, 0, 123701, 741, 7, 123701, "2022/10/15 15:00:00", 123701, 450, "【魔法】後衛で、オタ活に精を出すハロウィン魔法少女。\nＨＰ回復量ダウンで敵の戦略を崩し、ダメージフィールド\nと対象の数で火傷の威力を増す熱狂の炎が敵を包み込む。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2025/11/14 14:59:59", "くりすてぃーな", 3, 2.295, 0, 0, 1, 0, 1, "クリスティーナ（ワイルド）", 0, 1, 0, 0, 123801, 0, 123801, 238, 1, 123801, "2025/11/03 12:00:00", 123801, 450, "【物理】前衛で、戦場を跳ね回るラビット姿の誓約女君。\n物理攻撃を全て回避するスキルと攻撃力の強化で敵陣に\n単身特攻をかけ、ＵＢの範囲攻撃で敵を内から薙ぎ倒す。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "まつり", 3, 2.125, 0, 0, 0, 0, 1, "マツリ（ワイルド）", 0, 2, 0, 0, 123901, 0, 123901, 183, 2, 123901, "2022/11/15 15:00:00", 123901, 450, "【物理】前衛で母製の鎧を纏い気合い上々の獣人族騎士。\n自分のＨＰが低いほど与えるダメージと無効バリアの耐久\n力を高め、防御力ダウンと永続攻撃アップで活路を拓く。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2025/12/31 11:59:59", "あかり", 3, 2.07, 0, 0, 1, 0, 2, "アカリ（クリスマス）", 0, 7, 0, 0, 124001, 0, 124001, 438, 7, 124001, "2025/12/21 12:00:00", 124001, 450, "【魔法】中衛で、聖夜の街に幸せを運ぶ双子の妹サンタ。\n自分の魔法攻撃力に応じて効果が上がる味方全体への攻撃\n力強化に加え、単体特大魔法攻撃で勝利の旋律を奏でる。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "より", 1, 1.965, 0, 0, 1, 0, 2, "ヨリ（クリスマス）", 0, 6, 0, 0, 124101, 0, 124101, 433, 6, 124101, "2024/11/16 15:00:00", 124101, 450, "【魔法】中衛で、光を灯し幸せを届ける双子の姉サンタ。\n最も近い１キャラの魔法攻撃力や行動速度アップ、ＴＰの\n回復に加え、全員を支援するスキルで聖夜の勝利を飾る。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "じゅん", 3, 2.07, 0, 0, 0, 0, 1, "ジュン（クリスマス）", 0, 5, 0, 0, 124201, 0, 124201, 144, 5, 124201, "2022/12/23 12:00:00", 124201, 450, "【物理】前衛で、味方を庇護し祝福する聖白の騎士団長。\nスキルで後方の味方の攻撃能力を強化、ＴＰを回復させ、\n防御力ダウンと自分のＨＰを回復するＵＢで勝機を掴む。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (1, "2030/12/31 15:00:00", "あん", 3, 0.0, 0, 0, 1, 0, 0, "アン（アン＆グレア）", 0, 0, 0, 181001, 0, 0, 124301, 577, 0, 124301, "2015/04/01 15:00:00", 0, 0, "");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (1, "2030/12/31 15:00:00", "ぐれあ", 3, 0.0, 0, 0, 1, 0, 0, "グレア（アン＆グレア）", 0, 0, 0, 181001, 0, 0, 124401, 577, 0, 124401, "2015/04/01 15:00:00", 0, 0, "");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/01/31 11:59:59", "ほまれ", 3, 2.07, 0, 0, 1, 0, 2, "ホマレ（ニューイヤー）", 0, 21, 0, 0, 124501, 0, 124501, 707, 7, 124501, "2026/01/15 12:00:00", 124501, 450, "【魔法】後衛で、魔力を笑顔に隠す晴れ着姿の龍の首魁。\n自分の攻撃強化とＴＰ回復をし、ＵＢで放つ曙光の落涙は\n敵数で威力と防御力の減少量を上げ、全ての災厄を祓う。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/01/31 11:59:59", "みさと", 3, 2.44, 0, 0, 1, 0, 2, "ミサト（ニューイヤー）", 0, 21, 0, 0, 124601, 0, 124601, 698, 7, 124601, "2026/01/15 12:00:00", 124601, 450, "【魔法】後衛で真心重ねて味方をもてなす仲居姿の先生。\n全スキルで味方の物理攻撃力とクリティカル能力を上げ、\n魔防やＴＰ上昇の支援とＨＰ、ＴＰの回復で万福を願う。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "みつき", 1, 2.24, 0, 0, 1, 0, 1, "ミツキ（ニューイヤー）", 0, 46, 0, 0, 124701, 0, 124701, 590, 7, 124701, "2024/12/16 15:00:00", 124701, 450, "【物理】中衛で、振袖姿で旅館に手を貸す隻眼の闇医者。\n朧ろ状態にした敵への攻撃時、スキルのダメージや防御力\nのダウン値が上昇し、紫煙に捉えた敵を艶然と討ち取る。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/02/09 11:59:59", "のぞみ", 3, 2.14, 0, 0, 1, 0, 1, "ノゾミ（リベレイター）", 0, 0, 0, 0, 124801, 0, 124801, 423, 4, 124801, "2026/01/31 12:00:00", 124801, 450, "【物理】中衛で、未来を信じ希望を灯すトップアイドル。\nバトル開始時に物理キャラのＴＰ特大回復と敵の永続物防\nダウンで加勢し、物理攻撃強化とＴＰ回復で勝利へ導く。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "かや", 1, 1.965, 0, 0, 1, 0, 1, "カヤ（リベレイター）", 0, 0, 0, 0, 124901, 0, 124901, 170, 1, 124901, "2025/01/16 15:00:00", 124901, 450, "【物理】前衛で先陣を切り未来を掴む喧嘩屋ドラゴン族。\n初弾が大幅強化するスキルで自分の攻撃力とＴＰを大きく\n高め、威力を増したＵＢで先制し群がる敵を薙ぎ払う。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/02/09 11:59:59", "むいみ", 3, 1.965, 0, 0, 1, 0, 1, "ムイミ（リベレイター）", 0, 0, 0, 0, 125001, 0, 125001, 221, 5, 125001, "2026/01/31 12:00:00", 125001, 450, "【物理】前衛で、相棒と共に明日へと進む大悪党の少女。\n自己強化や物防ダウンを駆使するムイミと、ＵＢ後に一定\n時間共闘するオクトーの追撃で、輝く未来を取り戻す。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "たまき", 3, 2.24, 0, 0, 0, 0, 1, "タマキ（カフェ）", 0, 47, 0, 0, 125101, 0, 125101, 825, 8, 125101, "2023/03/03 19:00:00", 125101, 450, "【物理】後衛から客を癒しもてなす猫カフェ店員の猫娘。\n物攻の高いキャラの傍で周囲の物攻アップやＨＰとＴＰを\n回復し、周囲の味方数で強化される攻撃で敵を一掃する。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "もにか", 3, 1.965, 0, 0, 0, 0, 1, "モニカ（カフェ）", 0, 4, 0, 0, 125201, 0, 125201, 463, 4, 125201, "2023/03/10 12:00:00", 125201, 450, "【物理】中衛で、駄菓子を振舞い福を蒔く猫カフェ店員。\n攻撃を３回受けるまで味方全体の物理攻撃力を極大アップ\nさせ、２種の物防ダウンスキルで序盤を一気に加勢する。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/04/15 11:59:59", "こっころ", 3, 2.07, 0, 0, 1, 0, 1, "コッコロ（レンジャー）", 0, 6, 0, 0, 125301, 0, 125301, 752, 6, 125301, "2026/03/31 12:00:00", 125301, 450, "【物理】後衛で、わんわんと一緒の新緑レンジャー少女。\n自分の攻撃力に応じて強化される物理攻撃支援スキルや\nＨＰ継続回復、バリアで周囲を支え、絆の勝利へと導く。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "しおり", 3, 2.09, 0, 0, 0, 0, 1, "シオリ（レンジャー）", 0, 8, 0, 0, 125401, 0, 125401, 710, 8, 125401, "2023/04/10 12:00:00", 125401, 450, "【物理】後衛で、相棒と共に山を駆ける新米レンジャー。\nスキルで自分の攻撃力とクリティカル時のダメージを上げ\nＴＰを回復し、ダメージと防御力ダウンで敵を追い込む。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/05/31 11:59:59", "じーた", 3, 1.92, 0, 0, 1, 0, 2, "ジータ（ウォーロック）", 0, 50, 0, 0, 125501, 0, 125501, 443, 7, 125501, "2026/05/22 12:00:00", 125501, 450, "【魔法】中衛で、他の術者と魔力を束ねる究竟の魔導士。\n味方への魔法攻撃支援とＴＰ回復に加え、敵陣の攻防両面\nの弱体化で戦況を整え、自らも強力な攻撃魔法を放つ。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/05/31 11:59:59", "びから", 3, 2.09, 0, 0, 1, 0, 1, "ビカラ", 0, 0, 0, 0, 125601, 0, 125601, 267, 51, 125601, "2026/05/22 12:00:00", 125601, 450, "【物理】前衛で夢と希望とネズ耳を届ける鼠神宮の巫女。\n周囲の味方の物理攻撃支援、ＴＰ上昇アップと回復で援護\nし、自身の無敵化で敵の隙を突き鋭い金牙の一撃を放つ。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "かりん", 1, 2.24, 0, 0, 1, 0, 2, "カリン（アルケミスト）", 0, 9, 0, 0, 125701, 0, 125701, 579, 7, 125701, "2025/04/16 15:00:00", 125701, 450, "【魔法】中衛で森羅万象を究め味方を支援する錬金術師。\n物理、魔法の属性を問わない敵の弱体化と味方の強化に加\nえ、スキルによる高頻度のＨＰ回復で盤石な戦局を築く。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "りり", 3, 2.09, 0, 0, 0, 0, 1, "リリ（フォールン）", 0, 0, 0, 0, 125801, 0, 125801, 464, 3, 125801, "2023/04/17 12:00:00", 125801, 450, "【物理】中衛で、黒羽の力を使い空を制する嘆鎌の少女。\nバトル開始時に、敵の範囲攻撃を躱す【飛行】状態となり\n生成したシャドウと共に、眼前の敵を一薙ぎに斬り払う。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "かや", 3, 0.0, 0, 0, 1, 0, 0, "カヤ（リベレイター）", 0, 1, 0, 0, 0, 0, 125901, 0, 1, 125901, "2015/04/01 15:00:00", 0, 0, "");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "くりあ", 3, 2.09, 0, 0, 0, 0, 1, "クリア（フォールン）", 0, 0, 0, 0, 126001, 0, 126001, 406, 0, 126001, "2023/10/31 12:00:00", 126001, 450, "【物理】中衛から、我が身を盾に味方を守る隠棘の少女。\nバトル開始時【飛行】し、最もＨＰの低い味方をかばい、\n味方のＨＰに応じて強化されるスキルで敵を牽制する。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "ぷれしあ", 3, 2.09, 0, 0, 0, 0, 2, "プレシア（フォールン）", 0, 53, 0, 0, 126101, 0, 126101, 480, 44, 126101, "2023/11/15 15:00:00", 126101, 450, "【魔法】中衛で、マイペースに味方を支える破杖の少女。\n【飛行】し、クリティカルの強化やＨＰ・ＴＰ回復で味方\nを支援し、魔法攻撃力を加えた物理攻撃で敵を平らげる。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/06/30 11:59:59", "いりや", 3, 2.09, 0, 0, 1, 0, 2, "イリヤ（儀装束）", 0, 3, 0, 0, 126201, 0, 126201, 568, 3, 126201, "2026/06/22 12:00:00", 126201, 450, "【魔法】中衛で、眷属と永久の血盟を誓う月下の吸血鬼。\nＵＢで眷属を２体喚び、味方への攻撃支援や行動速度上昇\nで強化し、眷属と共に見舞う猛攻で前途を阻む敵を討つ。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "ゆき", 3, 2.07, 0, 0, 0, 0, 2, "ユキ（儀装束）", 0, 9, 0, 0, 126301, 0, 126301, 456, 7, 126301, "2023/06/15 15:00:00", 126301, 450, "【魔法】中衛で、闇色の儀装束を纏う「美を統べる者」。\nステータスアップ効果を受け【美貌】を増し、魔法攻撃力\nダウンや味方の強化、ＴＰ回復の効果を高めて解き放つ。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/08/26 11:59:59", "くろーちぇ", 3, 2.09, 0, 0, 1, 0, 1, "クローチェ", 0, 1, 0, 0, 126401, 0, 126401, 373, 1, 126401, "2026/08/23 12:00:00", 126401, 450, "【物理】中衛で着脱可能な鉄腕を放つ機械人族のロボ娘。\nＵＢ発動で【フルチャージ】状態になり、【バッテリー】\nが切れるまで強化スキルを連発し、一帯を超速圧砕する。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/08/26 11:59:59", "らいらえる", 3, 1.965, 0, 0, 1, 0, 2, "ライラエル", 0, 0, 0, 0, 126501, 0, 126501, 740, 7, 126501, "2026/08/23 12:00:00", 126501, 450, "【魔法】後衛で優美にほほ笑むジオ・テオゴニアの姫君。\n開始時に発動する【界雷】で、敵味方に影響を与えつつ、\n魔法防御ダウンと強力なダメージスキルで裁きを下す。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/07/31 11:59:59", "ねねか", 3, 2.04, 0, 0, 1, 0, 2, "ネネカ（サマー）", 0, 7, 0, 0, 126601, 0, 126601, 650, 7, 126601, "2026/07/15 12:00:00", 126601, 450, "【魔法】後衛で、涼しげに微笑む夏色姿の『変貌大妃』。\nスキルで味方を大幅に強化し、最も魔法攻撃力が高い味方\nの魔法攻撃力を写し取った攻撃力で、強力なＵＢを放つ。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "あきの", 1, 1.965, 0, 0, 1, 0, 1, "アキノ（サマー）", 0, 5, 0, 0, 126701, 0, 126701, 224, 5, 126701, "2025/06/17 15:00:00", 126701, 450, "【物理】前衛で、優雅なバカンスを過ごす夕映えの令嬢。\n敵が魔法攻撃をする場合に効果を大幅に上げる２種の範囲\n攻撃と攻防両面の支援スキルで、盛夏の勝鬨を上げる。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "ゆかり", 3, 1.97, 0, 0, 0, 0, 1, "ユカリ（サマー）", 0, 5, 0, 0, 126801, 0, 126801, 159, 5, 126801, "2023/07/15 15:00:00", 126801, 450, "【物理】前衛で、夏の麦しゅわを嗜むビーチの元聖騎士。\n敵単体にダメージを与えながら、周囲の味方への魔法無効\nバリア付与と魔防アップで守りを固めて勝利の波に乗る。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/08/31 11:59:59", "らんふぁ", 3, 1.965, 0, 0, 1, 0, 2, "ランファ（サマー）", 0, 21, 0, 0, 126901, 0, 126901, 682, 7, 126901, "2026/08/26 12:00:00", 126901, 450, "【魔法】後衛で、密やかな潮騒に耳を傾ける晩陽の歌姫。\n魔法クリティカルの極大アップを筆頭に攻防両面で周囲の\n味方を強化し、さらに自身もＵＢで数多の敵を退かせる。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "くうか", 1, 1.97, 0, 0, 1, 0, 1, "クウカ（サマー）", 0, 52, 0, 0, 127001, 0, 127001, 133, 2, 127001, "2025/07/16 15:00:00", 127001, 450, "【物理】前衛で新たな刺激を追い求める水着姿のドＭ娘。\n自分のＨＰが下がるほど効果量が上昇するスキルの物理攻\n撃力アップとＵＢのダメージで、勝利の大海へ飛び込む。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/08/31 11:59:59", "しのぶ", 3, 2.09, 0, 0, 1, 0, 1, "シノブ（サマー）", 0, 46, 0, 0, 127101, 0, 127101, 255, 5, 127101, "2026/08/26 12:00:00", 127101, 450, "【物理】前衛で、穏やかな水面に揺蕩う夜光の霊能少女。\n召喚した親父に敵の攻撃を引き付けさせつつ、シノブ自身\nの攻撃性能強化と防御ダウンを扱い、敵を冥海へと誘う。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2025/09/30 11:59:59", "きゃる", 3, 2.09, 0, 0, 1, 0, 2, "キャル（編入生）", 0, 7, 0, 0, 127201, 0, 127201, 804, 7, 127201, "2025/09/16 15:00:00", 127201, 450, "【魔法】後衛で、制服姿に胸を高鳴らせるアオハル猫娘。\n攻防両面のサポートに加え行動速度アップとＴＰ回復で味\n方を支援し、最も遠くの敵を狙うＵＢで輝く勝利を得る。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "すずな", 3, 2.09, 0, 0, 0, 0, 1, "スズナ（編入生）", 0, 8, 0, 0, 127301, 0, 127301, 750, 8, 127301, "2023/09/15 15:00:00", 127301, 450, "【物理】後衛でもにカワ制服を着こなすカリスマモデル。\nクリティカル時に味方を強化するスキルや、追加ダメージ\nが発生するＵＢによって青春の一ページを切り取る。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "びから", 3, 0.0, 0, 0, 1, 0, 0, "ビカラ（コラボ）", 0, 1, 0, 0, 0, 0, 127401, 0, 1, 127401, "2015/04/01 15:00:00", 0, 0, "");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/02/09 11:59:59", "されん", 3, 2.09, 0, 0, 1, 0, 1, "サレン（サラサリア）", 0, 4, 0, 0, 127501, 0, 127501, 304, 4, 127501, "2026/01/31 12:00:00", 127501, 450, "【物理】中衛で、優艶に炎と踊り舞う情熱のサレンママ。\n物理攻撃から味方を守り、【炎舞の刻印】の数に応じて効\n果の上がる物攻アップとＴＰ回復で皆を奮い立たせる。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "るか", 3, 1.965, 0, 0, 0, 0, 1, "ルカ（サラサリア）", 0, 4, 0, 0, 127601, 0, 127601, 157, 4, 127601, "2023/10/15 15:00:00", 127601, 450, "【物理】前衛で、空飛ぶ絨毯で巡り回るオアシスの姉御。\n自分の物防を大幅に高めて敵を挑発するスキルと敵のＴＰ\nとＴＰ上昇をダウンさせるＵＢで、爽やかに勝利を掴む。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "りんど", 3, 1.965, 0, 0, 0, 0, 2, "リンド", 0, 48, 0, 0, 127701, 0, 127701, 693, 6, 127701, "2024/10/10 12:00:00", 127701, 450, "【魔法】後衛で、メイド業に奔走する双子ドラゴンの姉。\nＵＢのフィールド展開中は攻撃、防御、ＴＰ回復と多彩な\n支援スキルの効果が再発動し味方を手厚くサポートする。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "うるむ", 3, 1.965, 0, 0, 0, 0, 2, "ヴルム", 0, 47, 0, 0, 127801, 0, 127801, 706, 7, 127801, "2024/10/18 12:00:00", 127801, 450, "【魔法】後衛で、文句を言いつつ働く双子ドラゴンの妹。\nダメージと魔法防御力ダウンを両立するスキルを持つが、\n目を離すと【サボりの誘惑】に負け、手を抜いてしまう。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2025/12/31 11:59:59", "ぺこりーぬ", 3, 1.965, 0, 0, 1, 0, 2, "ペコリーヌ（クリスマス）", 0, 5, 0, 0, 127901, 0, 127901, 372, 5, 127901, "2025/12/21 12:00:00", 127901, 450, "【魔法】中衛でみんなに笑顔を届ける腹ペコサンタ王女。\n前線で敵の攻撃を耐えながら範囲内の味方の防御サポート\nと敵の防御ダウンまでこなし、聖夜に勝利の輝きを灯す。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "くれじった", 3, 2.09, 0, 0, 0, 0, 1, "クレジッタ（クリスマス）", 0, 35, 0, 0, 128001, 0, 128001, 723, 35, 128001, "2023/12/15 15:00:00", 128001, 450, "【物理】後衛で、甘美なひと時を堪能する聖夜の女商人。\n最も遠い味方へのＴＰ回復や、初弾に追加効果のある攻撃\nで敵の弱体化と味方の強化を行い、勝利の舞台を整える。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (1, "2030/12/31 15:00:00", "しずる", 3, 0.0, 0, 0, 1, 0, 0, "シズル（シズル&リノ）", 0, 0, 0, 181101, 0, 0, 128101, 580, 0, 128101, "2015/04/01 15:00:00", 0, 0, "");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (1, "2030/12/31 15:00:00", "りの", 3, 0.0, 0, 0, 1, 0, 0, "リノ（シズル&リノ）", 0, 0, 0, 181101, 0, 0, 128201, 580, 0, 128201, "2015/04/01 15:00:00", 0, 0, "");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "いのり", 1, 2.09, 0, 0, 1, 0, 1, "イノリ（ニューイヤー）", 0, 38, 0, 0, 128301, 0, 128301, 191, 3, 128301, "2026/01/16 15:00:00", 128301, 450, "【物理】前衛で相手をからかうお調子者の年神ドラゴン。\n敵全体を挑発し、敵の妨害スキルにカウンターして前方の\n敵すべてをスタンさせるスキルで戦局を引っ掻き回す。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/01/31 11:59:59", "はつね", 3, 2.09, 0, 0, 1, 0, 2, "ハツネ（ニューイヤー）", 0, 21, 0, 0, 128401, 0, 128401, 801, 7, 128401, "2026/01/15 12:00:00", 128401, 450, "【魔法】後衛で特別な景色を共にする初夢超能力ガール。\n敵が物理攻撃を行う場合、攻撃性能の強化に加えて複数の\n弱体効果が追加され、攻守ともに味方を支援し敵を掃う。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/01/31 11:59:59", "かすみ", 3, 2.09, 0, 0, 1, 0, 2, "カスミ（ニューイヤー）", 0, 21, 0, 0, 128501, 0, 128501, 739, 7, 128501, "2026/01/15 12:00:00", 128501, 450, "【魔法】後衛で、絵馬に秘めた願いを祷る新年の名探偵。\n敵と味方の数で効果量が上昇するダメージと攻撃力支援に\n加え、２種類の回復スキルを使いこなして勝利を願う。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "りり", 3, 0.0, 0, 0, 1, 0, 0, "リリ（フォールン）", 0, 1, 0, 0, 0, 0, 128601, 0, 1, 128601, "2015/04/01 15:00:00", 0, 0, "");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/02/09 11:59:59", "ひより", 3, 2.09, 0, 0, 1, 0, 1, "ヒヨリ（アストラル）", 0, 0, 0, 0, 128701, 0, 128701, 226, 1, 128701, "2026/01/31 12:00:00", 128701, 450, "【物理】前衛で、煌炎宿し希望を振りまく覚醒の元気娘。\n放つ炎は敵を攻守ともに弱化させて同時に味方を鼓舞し、\n２種のＴＰ回復効果で攻勢を絶やさず勝利を呼び込む。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "れい", 1, 1.965, 0, 0, 1, 0, 1, "レイ（アストラル）", 0, 0, 0, 0, 128801, 0, 128801, 194, 4, 128801, "2025/08/16 15:00:00", 128801, 450, "【物理】前衛で、旋風を纏い未来へ駆ける覚醒の剣士。\n目にも止まらぬ速さの剣技で敵を吹き飛ばしスタンさせ、\n仲間の守りを固めるスキルを駆使し勝利の道を切り開く。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/02/09 11:59:59", "ゆい", 3, 2.09, 0, 0, 1, 0, 2, "ユイ（アストラル）", 0, 0, 0, 0, 128901, 0, 128901, 772, 7, 128901, "2026/01/31 12:00:00", 128901, 450, "【魔法】後衛で、願いを力に極光を放つ覚醒の魔法士。\n自分を強化しながら高火力魔法を絶えず撃ち込み、バリア\nを起点とした味方への攻撃支援スキルで勝利を手にする。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/08/26 11:59:59", "えりす", 3, 2.09, 0, 0, 1, 0, 2, "エリス", 0, 0, 0, 0, 129001, 0, 129001, 800, 7, 129001, "2026/08/23 12:00:00", 129001, 450, "【魔法】後衛で、眠りから目覚め美しく咲き誇る黒薔薇。\n終焉を超えし【回帰の薔薇】と、行動速度アップを始めと\nした多種の攻防支援で味方を強化し、新たな未来を掴む。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/03/31 11:59:59", "ゆに", 3, 2.09, 0, 0, 1, 0, 1, "ユニ（ウィンター）", 0, 7, 0, 0, 129301, 0, 129301, 708, 7, 129301, "2026/03/16 10:00:00", 129301, 450, "【物理】後衛で、退廃的な冬の学びに溺れる水際の才媛。\n物理攻撃の強化、回復、行動速度アップで味方を支援し、\nＵＢで得た【水際の安寧】を死守するため膂力を振るう。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "くろえ", 3, 2.09, 0, 0, 0, 0, 1, "クロエ（ウィンター）", 0, 2, 0, 0, 129401, 0, 129401, 188, 2, 129401, "2024/03/18 12:00:00", 129401, 450, "【物理】前衛で、水面に映る神速のダウナー系水着女子。\n攻撃を当てる度に敵に付与する【水月】の数に応じて物防\nダウンやダメージの効果が上昇し、必勝の抜き手を切る。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2025/12/15 14:59:59", "ちえる", 3, 2.09, 0, 0, 1, 0, 1, "チエル（ウィンター）", 0, 1, 0, 0, 129501, 0, 129501, 247, 1, 129501, "2025/11/30 12:00:00", 129501, 450, "【物理】前衛で、ちぇるっとちぇるるな水着のちえるん。\nステータスアップで溜まる【ちぇる】を、自身の火力や\n支援能力に還元して、真冬の真夏をちぇらるれれぽぱぴ？");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/08/26 11:59:59", "あねもね", 3, 2.09, 0, 0, 1, 0, 1, "アネモネ", 0, 0, 0, 0, 129601, 0, 129601, 550, 0, 129601, "2026/08/23 12:00:00", 129601, 450, "【物理】中衛で怜悧麗花の陣を張るアルラウネの妖魔人。\n敵の攻撃力、防御力、与ダメージを下げ、ＴＰを吸収し、\nＵＢの継続ダメージで領域を侵す敵を絶えず拒み退ける。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/08/26 11:59:59", "ねふぃーねら", 3, 2.09, 0, 0, 1, 0, 1, "ネフィ＝ネラ", 0, 0, 0, 0, 129701, 0, 129701, 540, 0, 129701, "2026/08/23 12:00:00", 129701, 450, "【物理】中衛で万魔の頂点に君臨するジオ・ゲヘナの媛。\n環境効果【妨魔塵】で魔法攻撃を阻害し、行動速度アップ\n等の支援や苛烈な攻撃で無謀な不届き者を平伏させる。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/04/15 11:59:59", "まこと", 3, 2.09, 0, 0, 1, 0, 1, "マコト（コマンダー）", 0, 5, 0, 0, 129801, 0, 129801, 269, 5, 129801, "2026/03/31 12:00:00", 129801, 450, "【物理】前衛で、情と熱意で仲間を束ねる指揮官の狼娘。\n敵の攻守を削りつつ、自分のＴＰ回復や対象が物防ダウン\n状態の時に発生する追撃で猛攻を仕掛け前線を突破する。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "えりこ", 3, 1.84, 0, 0, 0, 0, 1, "エリコ（コマンダー）", 0, 48, 0, 0, 129901, 0, 129901, 294, 6, 129901, "2024/04/15 15:00:00", 129901, 450, "【物理】前衛で、苛烈な教えで味方を率いる狂恋の教官。\nＴＰ回復や防御支援に加え味方の人数で効果アップする攻\n撃支援と大ダメージで、味方全体を奮い立たせ敵を破る。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2025/11/14 14:59:59", "やまと", 3, 2.09, 0, 0, 1, 0, 1, "ヤマト", 0, 0, 0, 0, 130001, 0, 130001, 150, 4, 130001, "2025/11/03 12:00:00", 130001, 450, "【物理】前衛で、豪胆にスリルを嗜む盗賊ギルドの長女。\n最前線で命を張りながら、獲得した【バンディダイス】の\n消費によって自らを大幅強化し、有象無象を地に伏せる。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2025/11/14 14:59:59", "わかな", 3, 2.09, 0, 0, 1, 0, 1, "ワカナ", 0, 9, 0, 0, 130101, 0, 130101, 535, 7, 130101, "2025/11/03 12:00:00", 130101, 450, "【物理】中衛の、貧乏クジを引きがちな盗賊ギルド次女。\n召喚したスキッドがワカナをかばって前線に立ち、自身は\n攻撃支援にＨＰとＴＰ回復まで、献身的に味方を支える。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2025/11/14 14:59:59", "ふぶき", 3, 1.84, 0, 0, 1, 0, 1, "フブキ", 0, 0, 0, 0, 130201, 0, 130201, 371, 5, 130201, "2025/11/03 12:00:00", 130201, 450, "【物理】中衛の、ナマイキで超天才な盗賊ギルドの三女。\n【味方バリアー♡】で自分へのダメージを味方に押し付け\nＨＰ最大でダメージアップする範囲攻撃で敵を蹂躙する。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "れい", 3, 0.0, 0, 0, 1, 0, 0, "レイ（アストラル）", 0, 1, 0, 0, 0, 0, 130601, 0, 4, 130601, "2015/04/01 15:00:00", 0, 0, "");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/05/31 11:59:59", "きょうか", 3, 1.92, 0, 0, 1, 0, 2, "キョウカ（スプリング）", 0, 7, 0, 0, 130701, 0, 130701, 563, 7, 130701, "2026/05/22 12:00:00", 130701, 450, "【魔法】中衛で、お花畑に春を届ける花衣装の優等生。\nスキル発動回数に応じた効率的な自己強化やクリティカル\n時の追加効果を持つスキルとＵＢで勝利の風を吹かせる。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "すずめ", 3, 1.84, 0, 0, 0, 0, 2, "スズメ（スプリング）", 0, 7, 0, 0, 130801, 0, 130801, 558, 7, 130801, "2024/05/15 15:00:00", 130801, 450, "【魔法】中衛で、春に彩られた花衣装のドジっ娘メイド。\n範囲内の敵にダメージを与えながら、多数の弱体化効果を\n持つスキルやＵＢを駆使して、穏やかに吹く勝利を掴む。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "くるる", 3, 2.09, 0, 0, 0, 0, 2, "クルル", 0, 7, 0, 0, 130901, 0, 130901, 440, 7, 130901, "2024/06/15 15:00:00", 130901, 450, "【魔法】中衛で、皆を夢の世界に誘う宝石兎族の支配人。\nステータスアップ効果を受けるたびに【かばばん君】を増\nやし、反射的に味方へ攻撃支援の恩返しをしてしまう。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/06/30 11:59:59", "まほ", 3, 1.84, 0, 0, 1, 0, 2, "マホ（ドリームパーク）", 0, 7, 0, 0, 131001, 0, 131001, 702, 7, 131001, "2026/06/22 12:00:00", 131001, 450, "【魔法】後衛で、サーカスの舞台に輝くメルヘン少女。\n味方の攻防支援や敵の攻防弱体化の他【カーテンコール】\n付与時の追加ダメージスキルで、勝利のライトを照らす。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "ねあ", 3, 2.09, 0, 0, 0, 0, 1, "ネア（サマー）", 0, 52, 0, 0, 131101, 0, 131101, 165, 2, 131101, "2024/06/30 12:00:00", 131101, 450, "【物理】前衛でハグの機会を窺う水着のスライムギャル。\n攻撃してきた敵に【ネバネバ】を自動で付着させ、攻撃力\nダウンやダメージ、束縛など複数の効果を引き起こす。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/07/31 11:59:59", "みそら", 3, 2.09, 0, 0, 1, 0, 2, "ミソラ（サマー）", 0, 54, 0, 0, 131201, 0, 131201, 753, 54, 131201, "2026/07/15 12:00:00", 131201, 450, "【魔法】後衛で夏の盛りにイイコトをする溌溂水着少女★\n【PSI★ストーム】をチャージし、連続攻撃で敵を殲滅し\nて、継続ＴＰ回復やバリアで抜け目なく味方を支援する。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (1, "2030/12/31 15:00:00", "りり", 3, 0.0, 0, 0, 1, 0, 0, "リリ", 0, 1, 0, 0, 0, 0, 131301, 0, 1, 131301, "2015/04/01 15:00:00", 0, 0, "");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (1, "2030/12/31 15:00:00", "くりあ", 3, 0.0, 0, 0, 1, 0, 0, "クリア", 0, 1, 0, 0, 0, 0, 131401, 0, 1, 131401, "2015/04/01 15:00:00", 0, 0, "");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (1, "2030/12/31 15:00:00", "ぷれしあ", 3, 0.0, 0, 0, 1, 0, 0, "プレシア", 0, 1, 0, 0, 0, 0, 131501, 0, 1, 131501, "2015/04/01 15:00:00", 0, 0, "");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/07/31 11:59:59", "りり", 3, 1.92, 0, 0, 1, 0, 1, "リリ（サマー）", 0, 4, 0, 0, 131601, 0, 131601, 399, 4, 131601, "2026/07/15 12:00:00", 131601, 450, "【物理】中衛で、夏の陽光のもと研鑽する妹系大和撫子。\n防御力アップに加えバリアやＨＰ回復で味方の守りを固め\nＴＰ回復や攻撃力ダウンをも巧みに操り、場を支配する。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/08/31 11:59:59", "あめす", 3, 1.92, 0, 0, 1, 0, 2, "アメス（サマー）", 0, 53, 0, 0, 131701, 0, 131701, 743, 44, 131701, "2026/08/26 12:00:00", 131701, 450, "【魔法】後衛で、黄昏の水面に舞い降りる水着姿の妖精。\n行動速度アップやＴＰ支援をはじめとした多数のサポート\nを施しつつ、ＵＢの攻防弱体化で清爽に勝利へと導く。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "ほまれ", 3, 2.09, 0, 0, 0, 0, 2, "ホマレ（サマー）", 0, 21, 0, 0, 131801, 0, 131801, 709, 7, 131801, "2024/08/15 15:00:00", 131801, 450, "【魔法】後衛で夏の清涼に翼を休める水着姿の龍の首領。\n攻防弱体化に加え、ステータスダウン付与のたび増加する\n【日食】の数に応じたダメージで、抗う全てを灰に帰す。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (1, "2030/12/31 15:00:00", "えみりあ", 1, 2.09, 0, 1, 1, 0, 2, "エミリア（サマー）", 0, 23, 0, 0, 131901, 0, 131901, 725, 7, 131901, "2024/08/31 12:00:00", 131901, 450, "【魔法】後衛で、パックと共に戦う真夏のハーフエルフ。\n氷壁を生成するスキルや、強力なダメージと速度ダウンを\n付与するユニオンバーストで、敵の侵攻を食い止める。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2025/10/24 11:59:59", "えきどな", 3, 2.09, 0, 1, 1, 0, 2, "エキドナ（サマー）", 0, 21, 0, 0, 132001, 0, 132001, 775, 7, 132001, "2025/10/10 12:00:00", 132001, 450, "【魔法】後衛で未知の世界との邂逅に胸躍る強欲の魔女。\n鮮烈な攻撃魔法をはじめ、味方への攻撃支援、敵の弱体化\nから自己蘇生まで、あらゆる魔法を振るい、欲を満たす。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2025/10/24 11:59:59", "れむ", 3, 2.09, 0, 1, 1, 0, 1, "レム（サマー）", 0, 24, 0, 0, 132101, 0, 132101, 146, 13, 132101, "2025/10/10 12:00:00", 132101, 450, "【物理】前衛で夏の日差しの中、余暇を楽しむ双子の妹。\nＵＢで鬼族の力を解放すると攻防両面に加えＨＰ吸収が\n上昇し、目に映る全てを【狂騒】のままに叩き伏せる。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2025/10/31 11:59:59", "のぞみ", 3, 1.84, 0, 0, 1, 0, 2, "ノゾミ（アルケミスト）", 0, 7, 0, 0, 132201, 0, 132201, 721, 7, 132201, "2025/10/24 12:00:00", 132201, 450, "【魔法】後衛で、希望を錬成するアルケミストアイドル。\n【錬金素材】から【パフューム】を創り、ダメージに加え\nＴＰ回復や攻撃支援能力を向上させて勝利の香りを運ぶ。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/05/22 11:59:59", "るいずまりー", 3, 2.09, 0, 0, 1, 0, 2, "ルイズマリー", 0, 7, 0, 0, 132301, 0, 132301, 754, 7, 132301, "2026/05/11 12:00:00", 132301, 450, "【魔法】後衛で、底知れぬ叡智を秘めた天才錬金術師。\n高い方の防御力でダメージを受ける調和状態を付与し、\n２回まで性能が上昇していくＵＢで、妄想を爆発させる。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "いろは", 3, 2.09, 0, 0, 0, 0, 1, "イロハ", 0, 0, 0, 0, 132401, 0, 132401, 501, 5, 132401, "2025/06/20 12:00:00", 132401, 450, "【物理】中衛で、大きな体で無邪気に遊び回る天才剣士。\n戦いの中で【剣圧】を溜め、その後のスキルやＵＢで物防\n一定無視のダメージを連発し、才気煥発の活躍を見せる。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "その", 3, 2.09, 0, 0, 0, 0, 2, "ソノ", 0, 23, 0, 0, 132501, 0, 132501, 636, 7, 132501, "2025/05/15 15:00:00", 132501, 450, "【魔法】後衛で、小柄で大人対応な錬金堂の省エネ店主。\n強力な弱体効果を与えながら、デバフ付与のたび増加する\n【虚脱】が80溜まると本気を出し定時厳守で戦い抜く。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2025/12/15 14:59:59", "らいらえる", 3, 2.09, 0, 0, 1, 0, 2, "ライラエル（クリスマス）", 0, 0, 0, 0, 132801, 0, 132801, 750, 7, 132801, "2025/11/30 12:00:00", 132801, 450, "【魔法】後衛で、雪白の肌を黒衣に包んだ甘美なる姫君。\n味方のＨＰを代償に強力なバリアを展開しつつ、バリアを\n起点とした高出力の二連撃で、聖夜の大樹に灯を点す。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "いお", 3, 2.09, 0, 0, 0, 0, 2, "イオ（クリスマス）", 0, 46, 0, 0, 132901, 0, 132901, 748, 5, 132901, "2024/12/09 12:00:00", 132901, 450, "【魔法】後衛で、心地良い眠りの中に訪れる聖夜の悪魔。\n最も魔法攻撃力が高い味方に【悪魔の口づけ】を付与し、\n攻撃支援とＴＰ回復による付きっきりの手ほどきをする。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/08/26 11:59:59", "ぐれいす", 3, 2.09, 0, 0, 1, 0, 1, "グレイス", 0, 0, 0, 0, 133001, 0, 133001, 234, 0, 133001, "2026/08/23 12:00:00", 133001, 450, "【物理】前衛で、宙を舞うように戦う幽霊の守護騎士。\nＵＢで味方の攻撃と速度支援を行い、【レイスボディ】で\n敵の目を逃れ、不意を突く一撃で永遠の眠りにつかせる。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/08/26 11:59:59", "うぁいおれっと", 3, 1.75, 0, 0, 1, 0, 1, "ヴァイオレット", 0, 0, 0, 0, 133101, 0, 133101, 154, 0, 133101, "2026/08/23 12:00:00", 133101, 450, "【物理】前衛で、儚くも凛と咲くジオ・ニヴルヘルの姫。\n継続ダメージ効果を鈍化させる環境効果【忌火】で盾に、\n絶怠霊度の継続割合攻撃で矛となり、静寂の冥府を護る。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (1, "2030/12/31 15:00:00", "もにか", 1, 2.09, 0, 0, 1, 0, 1, "モニカ（ニューイヤー）", 0, 22, 0, 0, 133201, 0, 133201, 296, 4, 133201, "2024/12/31 12:00:00", 133201, 450, "【物理】前衛で、元日も元気にはしゃぎまわる軍人少女。\n与ダメージに応じて追加効果が強化されるＵＢと、発動ご\nとに成長する自己強化スキルで秩序を乱す者の目を回す。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/01/15 11:59:59", "されん", 3, 2.09, 0, 0, 1, 0, 2, "サレン（ニューイヤー）", 0, 22, 0, 0, 133501, 0, 133501, 718, 4, 133501, "2026/01/03 12:00:00", 133501, 450, "【魔法】後衛で、傍らで心を重ねる振袖姿の救護院の主。\n味方へのＴＰ回復の支援をしつつ、味方がＵＢを発動する\nたびダメージが上がるスキルで、共に困難を乗り越える。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/01/15 11:59:59", "めどぅーさ", 3, 2.09, 0, 0, 1, 0, 1, "メドゥーサ", 0, 0, 0, 0, 133601, 0, 133601, 445, 0, 133601, "2026/01/03 12:00:00", 133601, 450, "【物理】中衛で眷属と力を合わせて戦う誇り高き蛇乙女。\n【魔眼】の数に応じて効果量が上がるスキルのダメージと\n弱体化で範囲内の敵を追い詰め、鋭い瞳で石へと変える。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/02/15 11:59:59", "らびりすた", 3, 2.09, 0, 0, 1, 0, 2, "ラビリスタ（アルファ）", 0, 0, 0, 0, 133701, 0, 133701, 717, 8, 133701, "2026/02/09 12:00:00", 133701, 450, "【魔法】後衛で、始原の冠装を使いこなす『迷宮女王』。\n水属性の味方のＴＰ上昇を増加する領域を作り、連射攻撃\nで敵の防御を撃ち抜くことで七冠の力を敵に知らしめる。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/02/15 11:59:59", "ねねか", 3, 2.09, 0, 0, 1, 0, 2, "ネネカ（アルファ）", 0, 0, 0, 0, 133801, 0, 133801, 759, 7, 133801, "2026/02/09 12:00:00", 133801, 450, "【魔法】後衛から、始原の姿で戦況を操る『変貌大妃』。\n召喚したグレゴールから攻撃支援とＴＰ回復を受け、互い\nの魔力を合わせた連携攻撃で、幽玄なる玉座に君臨する。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/02/15 11:59:59", "くりすてぃーな", 3, 2.09, 0, 0, 1, 0, 1, "クリスティーナ（アルファ）", 0, 0, 0, 0, 133901, 0, 133901, 228, 6, 133901, "2026/02/09 12:00:00", 133901, 450, "【物理】前衛で、始原の冠装の力を振るう『誓約女君』。\n10行動目に攻撃力を大幅アップし、スキルに追撃を発生\nさせる【虚数】を得て隔絶した力で楯突く敵を抹消する。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/08/26 11:59:59", "ふぃお", 3, 2.09, 0, 0, 1, 0, 2, "フィオ", 0, 0, 0, 0, 134001, 0, 134001, 746, 0, 134001, "2026/08/23 12:00:00", 134001, 450, "【魔法】後衛で、アストルムの冒険へと導くガイド妖精。\nバフとバリアで味方を護りバリアを起点とする攻撃支援、\n風属性の味方への行動速度とＴＰの支援で仲間を支える。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "ふぶき", 3, 0.0, 0, 0, 1, 0, 0, "フブキ", 0, 1, 0, 0, 0, 0, 134101, 0, 5, 134101, "2015/04/01 15:00:00", 0, 0, "");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "らいらえる", 3, 0.0, 0, 0, 1, 0, 0, "ライラエル（クリスマス）", 0, 1, 0, 0, 0, 0, 134201, 0, 7, 134201, "2015/04/01 15:00:00", 0, 0, "");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/03/16 9:59:59", "らんふぁ", 3, 2.09, 0, 0, 1, 0, 2, "ランファ（儀装束）", 0, 0, 0, 0, 134301, 0, 134301, 778, 7, 134301, "2026/03/03 12:00:00", 134301, 450, "【魔法】後衛で儀装束を纏い精霊と心を通わせる唱喚士。\n敵の数に応じてダメージ量が変化する範囲攻撃や、魔法\n無効バリアなどの支援スキルで想いを詩に乗せ響かせる。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "ちか", 3, 2.09, 0, 0, 0, 0, 2, "チカ（儀装束）", 0, 21, 0, 0, 134401, 0, 134401, 773, 7, 134401, "2025/03/15 15:00:00", 134401, 450, "【魔法】後衛で儀装束を纏い歌を紡ぎ伝えていく唱喚士。\n自分と最も近くの味方へ強力なバフとＴＰ回復を行うこと\nで攻撃を支援し、共に心を通わせ美しき旋律を奏でる。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/04/30 11:59:59", "くろーちぇ", 3, 2.09, 0, 0, 1, 0, 2, "クローチェ（エアリアル）", 0, 0, 0, 0, 134501, 0, 134501, 719, 0, 134501, "2026/04/15 12:00:00", 134501, 450, "【魔法】後衛で超速飛行からの大火力を叩き込むロボ娘。\n上空から速度バフで味方全体を支援しつつ、自分のバリア\nを解除して力へと変え、世界の命運を背負い飛翔する！");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/04/30 11:59:59", "あおい", 3, 2.09, 0, 0, 1, 0, 1, "アオイ（パイロット）", 0, 35, 0, 0, 134601, 0, 134601, 526, 35, 134601, "2026/04/15 12:00:00", 134601, 450, "【物理】中衛で巨大ロボを駆り戦うぼっちのパイロット。\n敵の弱体化や、味方へバリアを展開するスキルを持ち、\n鋼鉄の乙女から放つ光線はいかに堅固な守りも打ち破る。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/04/30 11:59:59", "ほうおう", 3, 2.09, 0, 0, 1, 0, 1, "ホウオウ", 0, 7, 0, 0, 134701, 0, 134701, 490, 7, 134701, "2026/04/15 12:00:00", 134701, 450, "【物理】中衛で、華麗に舞い踊る五色絢爛な煉華の鳳凰。\n攻撃力バフやバリア展開などの攻防支援と、多彩で豊富な\nＨＰ・ＴＰ供給を両立し、浄化の力で皆に安寧を授ける。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/06/22 11:59:59", "つむぎ", 3, 1.84, 0, 0, 1, 0, 1, "ツムギ（ジオ・ゲヘナ）", 0, 1, 0, 0, 134801, 0, 134801, 485, 1, 134801, "2026/06/10 12:00:00", 134801, 450, "【物理】中衛から、新たな素材で紡ぐワイルドテーラー。\n最も物攻が高い他の味方へ重複速度アップやＴＰ・攻撃支\n援を仕立て、全体へのＨＰ回復と併せ攻守を両立させる。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/06/22 11:59:59", "かのん", 3, 2.09, 0, 0, 1, 0, 1, "カノン", 0, 0, 0, 0, 134901, 0, 134901, 196, 2, 134901, "2026/06/10 12:00:00", 134901, 450, "【物理】前衛で、おエレガントな高笑いを轟かすド令嬢。\nＵＢや敵からの攻撃で【お堪忍袋】が尽きると逆上し、強\n化されたスキルと行動パターンで華麗におリベンジする。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/07/15 11:59:59", "えりす", 3, 2.09, 0, 0, 1, 0, 2, "エリス（サマー）", 0, 21, 0, 0, 135001, 0, 135001, 785, 7, 135001, "2026/07/03 12:00:00", 135001, 450, "【魔法】後衛で、永く夢見た本物の夏に咲き綻ぶ黒薔薇。\n【いばらの冠】の呪縛は再臨により解き放たれ、調和状態\nや攻防支援、回復効果を施し、月下の浜辺に静かに佇む。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/07/15 11:59:59", "しぇふぃ", 3, 2.09, 0, 0, 1, 0, 1, "シェフィ（サマー）", 0, 4, 0, 0, 135101, 0, 135101, 143, 4, 135101, "2026/07/03 12:00:00", 135101, 450, "【物理】前衛で盛夏の白波を華麗に乗りこなす氷竜少女。\n敵全体を挑発し、被弾で溜まる【ぐずぐず】をＵＢで発散\nすることで周囲に攻撃支援と天真爛漫な笑顔を振りまく。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/07/15 11:59:59", "ぷれしあ", 3, 2.09, 0, 0, 1, 0, 2, "プレシア（サマー）", 0, 7, 0, 0, 135201, 0, 135201, 548, 7, 135201, "2026/07/03 12:00:00", 135201, 450, "【魔法】中衛で夏の食を満喫し、ぷかぷか漂う天然少女。\nＴＰ・攻撃支援やバリアは味方の数で効果量が変化し、物\n理と魔法攻撃力合算のダメージで夏の思い出を心に刻む。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/08/15 11:59:59", "くりあ", 3, 2.09, 0, 0, 1, 0, 1, "クリア（サマー）", 0, 54, 0, 0, 135301, 0, 135301, 413, 54, 135301, "2026/07/31 12:00:00", 135301, 450, "【物理】中衛で友情の芽を育む、真夏の『普通』の少女。\n【プルメリアのお守り】で強力な一撃から先頭を守り、味\n方の数で効果量が変化するスキルを鮮やかに命中させる。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/08/15 11:59:59", "あねもね", 3, 2.09, 0, 0, 1, 0, 2, "アネモネ（サマー）", 0, 52, 0, 0, 135401, 0, 135401, 553, 2, 135401, "2026/07/31 12:00:00", 135401, 450, "【魔法】中衛で砂浜の木陰に微睡むアルラウネの妖魔人。\n行動速度アップや初回発動時に回復量が増加するＴＰ回復\nを起点に支援し、穏やかな木漏れ日と共にゆらゆら憩う。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/08/26 11:59:59", "あいら", 3, 2.09, 0, 0, 1, 0, 1, "アイラ", 0, 0, 0, 0, 135501, 0, 135501, 213, 1, 135501, "2026/08/23 12:00:00", 135501, 450, "【物理】前衛で、世界を守り笑顔を咲かせる情熱の豪炎。\n前方の敵全てを対象とする連撃の強化通常攻撃や、天楼覇\n断剣から放たれる極大ダメージの一閃で未来を切り拓く。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/08/26 11:59:59", "しなつ", 3, 0.4, 0, 0, 1, 0, 1, "シナツ", 0, 0, 0, 0, 135601, 0, 135601, 198, 4, 135601, "2026/08/23 12:00:00", 135601, 450, "【物理】前衛から、風裂く刃で世界を護る孤高の剣豪。\n卓越した剣技で敵の攻撃を捌いて反撃し、初回ＵＢで生成\nする分身と共に疾風迅雷の攻めで、未来へと駆け抜ける。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "ひより", 3, 1.84, 0, 0, 0, 0, 1, "ヒヨリ（サラサリア）", 0, 0, 0, 0, 135701, 0, 135701, 291, 1, 135701, "2025/09/16 15:00:00", 135701, 450, "【物理】前衛で、二人きりの月下の空旅にときめく黒猫。\n物防弱体の他、ダメージ100ヒット後には華麗なステップ\nの追撃とＴＰ回復量増加で、砂漠の夜空に花を咲かせる。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/05/22 11:59:59", "ゆきの", 3, 2.09, 0, 0, 1, 0, 2, "ユキノ", 0, 0, 0, 0, 135801, 0, 135801, 830, 7, 135801, "2026/05/11 12:00:00", 135801, 450, "【魔法】後衛から、雪魄氷姿の三味を弾じる初心な雪女。\n多様なデバフ効果で敵を弱体化させ、最も魔防の低い敵の\n状態に応じて発生する追加効果で、冥府を真白に染める。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/05/22 11:59:59", "さつき", 3, 1.84, 0, 0, 1, 0, 1, "サツキ", 0, 0, 0, 0, 135901, 0, 135901, 219, 3, 135901, "2026/05/11 12:00:00", 135901, 450, "【物理】前衛で、華奢な体躯に厚い仁義を宿す鬼のお嬢。\n攻防自己強化や行動不能無効化で豪胆に立ち続け、自分が\n呪詛状態の時に振るう追加攻撃で、怪力無双の力を示す。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/08/26 11:59:59", "あらくね", 3, 2.09, 0, 0, 1, 0, 1, "アラクネ", 0, 0, 0, 0, 136001, 0, 136001, 732, 11, 136001, "2026/08/23 12:00:00", 136001, 450, "【物理】後衛で、喪われた光を求めてもがく元『六凶』。\n敵のＵＢを遅延する【遮絶の操糸】や、味方単体のＵＢを\n連続発動可能にする【賦活の糸】を戦場に張り巡らせる。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2025/11/03 11:59:59", "さくら", 3, 1.74, 0, 1, 1, 0, 1, "サクラ", 0, 0, 0, 0, 136101, 0, 136101, 432, 0, 136101, "2025/10/24 12:00:00", 136101, 450, "【物理】中衛で不運に抗い歌い続けるゾンビィアイドル。\n一度倒れても立ち上がり、ＴＰを糧に強化されるスキルの\nダメージと味方の支援で、サガの心をアストルムに刻む。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "なーな", 3, 2.09, 0, 0, 0, 0, 1, "ナーナ", 0, 3, 0, 0, 136201, 0, 136201, 198, 3, 136201, "2025/11/14 15:00:00", 136201, 450, "【物理】前衛でダメダメでも逃げず戦うアルミラージ娘。\n最も近くの味方に強化や行動不能無効の付与、回復を行い\n敵の注意をそらすことで、過酷な世界を生き延びる。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/07/15 11:59:59", "みそら", 3, 2.09, 0, 0, 1, 0, 2, "ミソラ（クリスマス）", 0, 54, 0, 0, 136301, 0, 136301, 655, 35, 136301, "2026/07/03 12:00:00", 136301, 450, "【魔法】後衛で、シゲキ的な聖夜に鼓動高鳴る溌溂少女★\n【イルミネーションバレット】を消費して味方を支援し、\n40消費後は追加の範囲攻撃やバフでキュン★を届ける。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/07/15 11:59:59", "ゆい", 3, 1.84, 0, 0, 1, 0, 2, "ユイ（クリスマス）", 0, 21, 0, 0, 136401, 0, 136401, 382, 7, 136401, "2026/07/03 12:00:00", 136401, 450, "【魔法】中衛で、騎士の隣に一歩踏み出す聖夜の魔法士。\n敵の注目を集めながら攻防支援を行い【聖夜の愛慕】が\n高まると、ＴＰ支援やダメージカットで優しく包み込む。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/08/23 11:59:59", "しずる", 3, 2.09, 0, 0, 1, 0, 1, "シズル（ニューイヤー）", 0, 0, 0, 0, 136501, 0, 136501, 151, 5, 136501, "2026/08/15 12:00:00", 136501, 450, "【物理】前衛で、凛然と立ちはだかる新年のお姉ちゃん。\n挑発と行動不能無効で攻撃を鮮やかに捌き、状況に応じて\n物理・魔法を自在に操り、弟くんへの愛を見せつける。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "めどぅーさ", 1, 0.0, 0, 0, 0, 0, 0, "メドゥーサ", 0, 1, 0, 0, 0, 0, 136601, 0, 1, 136601, "2015/04/01 15:00:00", 0, 0, "");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "らびりすた", 3, 0.0, 0, 0, 1, 0, 0, "ラビリスタ（アルファ）", 0, 1, 0, 0, 0, 0, 136701, 0, 8, 136701, "2015/04/01 15:00:00", 0, 0, "");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "らんふぁ", 3, 0.0, 0, 0, 1, 0, 0, "ランファ（儀装束）", 0, 1, 0, 0, 0, 0, 136801, 0, 7, 136801, "2015/04/01 15:00:00", 0, 0, "");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "るるぃ", 3, 2.09, 0, 0, 0, 0, 1, "ルルィ", 0, 0, 0, 0, 136901, 0, 136901, 409, 3, 136901, "2026/05/22 12:00:00", 136901, 450, "【物理】中衛でうねる、珍味な触手の小姓見習いタコ娘。\nＴＰ回復、継続ＨＰ回復、バリアで味方をもてなし、多様\nな弱体効果を与える自慢の墨で、敵を真っ黒に染める。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "にのん", 3, 2.09, 0, 0, 0, 0, 2, "ニノン（サマー）", 0, 47, 0, 0, 137101, 0, 137101, 566, 8, 137101, "2025/08/15 15:00:00", 137101, 450, "【魔法】中衛で陽光の下、煌く水面を共に駆けるシノビ。\n【水遁の印】を自らの攻撃力へと変え、束縛フィールドと\n水遁の術で最も遠い敵とその周囲に速やかな天誅を下す。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "らびりすた", 3, 0.0, 0, 0, 0, 0, 0, "ラビリスタ", 0, 2, 0, 0, 0, 0, 137201, 0, 2, 137201, "2015/04/01 15:00:00", 0, 0, "");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "かのん", 3, 0.0, 0, 0, 1, 0, 0, "カノン", 0, 1, 0, 0, 0, 0, 137301, 0, 2, 137301, "2015/04/01 15:00:00", 0, 0, "");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/06/22 11:59:59", "かすみ", 3, 2.09, 0, 0, 1, 0, 2, "カスミ（シスター）", 0, 21, 0, 0, 137401, 0, 137401, 688, 7, 137401, "2026/06/10 12:00:00", 137401, 450, "【魔法】後衛で、聖なる光に包まれ微笑み祈るシスター。\n攻防デバフを操り【真実の導き】が集まると最大３キャラ\nへの攻撃が最も魔防の低い敵を追及し、真理を照らす。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "あいら", 3, 0.0, 0, 0, 1, 0, 0, "アイラ", 0, 1, 0, 0, 0, 0, 137501, 0, 1, 137501, "2015/04/01 15:00:00", 0, 0, "");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/08/26 11:59:59", "こっころ", 3, 2.09, 0, 0, 1, 0, 2, "コッコロ（嚮導幼君）", 0, 0, 0, 0, 137601, 0, 137601, 733, 7, 137601, "2026/08/23 12:00:00", 137601, 450, "【魔法】後衛で、主さまを想い“進化”した嚮導の巫女。\n極大ダメージのＵＢで敵を穿ち、【進化超越】の権能によ\nって、味方のバフやダメージを、限界を超え成長させる。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "ゆきの", 3, 0.0, 0, 0, 1, 0, 0, "ユキノ", 0, 1, 0, 0, 0, 0, 137801, 0, 7, 137801, "2015/04/01 15:00:00", 0, 0, "");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/08/23 11:59:59", "りの", 3, 2.09, 0, 0, 1, 0, 2, "リノ（ニューイヤー）", 0, 8, 0, 0, 137901, 0, 137901, 684, 8, 137901, "2026/08/15 12:00:00", 137901, 450, "【魔法】後衛で絵馬に込めた想いを胸に抱く晴れ着の妹。\nクリティカル時に威力が上がる矢で敵を撃ち抜き、味方\n全体への攻撃支援や継続ＴＰ回復で厄を払い福を届ける。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/02/09 11:59:59", "うぁいおれっと", 3, 2.09, 0, 0, 1, 0, 1, "ヴァイオレット（イサナミ）", 0, 0, 0, 0, 138001, 0, 138001, 154, 0, 138001, "2026/01/31 12:00:00", 138001, 450, "【物理】前衛から慈愛の心で冥府を包む彼岸の屍姫。\nＵＢは敵全体を呑み込む割合ダメージを与え、【冥海の加\n護】を消費して味方の攻防ダウン効果までも禊ぎ清める。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/02/15 11:59:59", "らいらえる", 3, 2.09, 0, 0, 1, 0, 2, "ライラエル（パルフェクト）", 0, 0, 0, 0, 138101, 0, 138101, 729, 0, 138101, "2026/02/09 12:00:00", 138101, 450, "【魔法】後衛で、民とハーモニーを奏でる天使の姫君。\nステータスアップ効果を受け【エクスマキナ】が溜まると\n行動パターンが変化し、絶え間ない弓撃で神威を示す。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/02/28 11:59:59", "ねふぃーねら", 3, 2.09, 0, 0, 1, 0, 1, "ネフィ＝ネラ（鬼面仏心）", 0, 0, 0, 0, 138201, 0, 138201, 502, 0, 138201, "2026/02/15 12:00:00", 138201, 450, "【物理】中衛から怯懦を退け、万魔を率する煉獄の鉄媛。\n千変万化の躰は行動速度アップを始めとする多彩な支援と\nすべての敵の弱体を両立し、天地万象を掌の内に収める。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/08/26 11:59:59", "ぺこりーぬ", 3, 2.09, 0, 0, 1, 0, 1, "ペコリーヌ（アストライア）", 0, 0, 0, 0, 138301, 0, 138301, 142, 0, 138301, "2026/08/23 12:00:00", 138301, 450, "【物理】前衛で女神の血脈と矜持を揮う全力全開の王女。\n物理攻撃力の高い味方を【裁定の盾】で庇い、自身は圧倒\n的な防御とＨＰ回復で前線に立ち幸せな食卓を守り抜く。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "さくら", 3, 0.0, 0, 0, 1, 0, 0, "サクラ", 0, 1, 0, 0, 0, 0, 138601, 0, 1, 138601, "2015/04/01 15:00:00", 0, 0, "");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/03/16 9:59:59", "わかな", 3, 2.09, 0, 0, 1, 0, 1, "ワカナ（ウィンター）", 0, 55, 0, 0, 138701, 0, 138701, 539, 7, 138701, "2026/03/03 12:00:00", 138701, 450, "【物理】中衛で恥じらいながらも激戦に飛び込む桃闘者。\n味方を【スパイクシール】で守りつつ、自身は物理防御力\nダウンで敵を切り崩し、鍛え上げた桃尻を存分に振るう。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/03/31 11:59:59", "しおり", 3, 2.09, 0, 0, 1, 0, 1, "シオリ（ウィンター）", 0, 8, 0, 0, 138801, 0, 138801, 571, 8, 138801, "2026/03/16 10:00:00", 138801, 450, "【物理】中衛で、過酷なお尻の世界を生き抜く桃闘者。\n攻防ダウンを併せ持つＵＢを矢継ぎ早に放ち、ステータス\nダウン効果で付与する【魅惑の矢】で敵を骨抜きにする。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/04/10 11:59:59", "ぐれいす", 3, 2.09, 0, 0, 1, 0, 1, "グレイス（バニー）", 0, 0, 0, 0, 138901, 0, 138901, 429, 4, 138901, "2026/03/31 12:00:00", 138901, 450, "【物理】中衛で、妖しく跳ねるバニーの幽霊守護騎士。\n物理攻撃力を代償に物理クリダメを極大アップし、【ブラ\nックうさ耳】で油断した敵の虚を突き、御首を頂戴する。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/04/22 11:59:59", "きょうか", 3, 2.09, 0, 0, 1, 0, 2, "キョウカ（ゴシック）", 0, 7, 0, 0, 139001, 0, 139001, 816, 7, 139001, "2026/04/10 12:00:00", 139001, 450, "【魔法】後衛で、破滅の運命にあらがうお嬢様？優等生。\n【呪いの鎖】の溢れる魔力で魔防デバフやＴＰ、速度支援\nを行うが、限界を迎えると永久的狂気に陥ってしまう。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/08/26 11:59:59", "きゃる", 3, 2.09, 0, 0, 1, 0, 2, "キャル（覇瞳天星）", 0, 0, 0, 0, 139101, 0, 139101, 770, 0, 139101, "2026/08/23 12:00:00", 139101, 450, "【魔法】後衛で、天の星を瞳に映し、仲間と進む黒猫娘。\n敵全体を激烈に弱体化させながら、【千里真眼】状態時に\n未来を視通す能力で仲間をあらゆる脅威から遠ざける。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (1, "2030/12/31 15:00:00", "みほ", 1, 2.09, 0, 1, 1, 0, 2, "ミホ（ガルパン）", 0, 0, 0, 0, 139201, 0, 139201, 486, 0, 139201, "2026/04/30 12:00:00", 139201, 450, "【魔法】中衛で臨機応変に作戦を指揮する戦車道の乙女。\n召喚したボコが敵の攻撃を引き付けている間に、周囲の\n味方の攻撃、回復支援によって、全員での勝利を目指す。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/05/22 11:59:59", "まほ", 3, 2.09, 0, 1, 1, 0, 1, "マホ（ガルパン）", 0, 0, 0, 0, 139301, 0, 139301, 700, 0, 139301, "2026/04/30 12:00:00", 139301, 450, "【物理】後衛から必中の一射で敵を貫く西住流の継承者。\n【榴弾】を装填した状態のＵＢは、防御力を無視する火傷\nフィールドを発生させ、圧倒的な戦力差で敵を蹂躙する。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/05/22 11:59:59", "えりか", 3, 1.04, 0, 1, 1, 0, 1, "エリカ（ガルパン）", 0, 0, 0, 0, 139401, 0, 139401, 322, 0, 139401, "2026/05/11 12:00:00", 139401, 450, "【物理】中衛から迅速な強襲で戦局を切り拓く双剣使い。\nバトル開始直後からＴＰを消費する強力なスキルの連撃で\n敵の防御力を一気に下げ、敵陣深くまで浸透突破する。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/06/10 11:59:59", "りり", 3, 2.09, 0, 0, 1, 0, 2, "リリ（ヴァルキュリア）", 0, 0, 0, 0, 139501, 0, 139501, 453, 0, 139501, "2026/05/31 12:00:00", 139501, 450, "【魔法】中衛で、寄る辺無き魂を繋ぎ導く清廉の戦乙女。\nダメージと共に敵の魔防を削ぎ、継続ダメージを与える聖\n浄の光が戦乙女の聖槍を降り注がせ、敵を清め祓う。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/06/30 11:59:59", "くりあ", 3, 2.09, 0, 0, 1, 0, 2, "クリア（ヴァルキュリア）", 0, 0, 0, 0, 139601, 0, 139601, 150, 2, 139601, "2026/06/22 12:00:00", 139601, 450, "【魔法】前衛で、奇跡により魂の疵を癒す浄罪の戦乙女。\n味方を物理攻撃から堅牢に守り、継続ダメージを与える聖\n浄の光を敵に浴びせ、戦乙女の聖槍による天罰を下す。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/06/22 11:59:59", "ぷれしあ", 3, 2.09, 0, 0, 1, 0, 2, "プレシア（ヴァルキュリア）", 0, 0, 0, 0, 139701, 0, 139701, 500, 0, 139701, "2026/06/10 12:00:00", 139701, 450, "【魔法】中衛で、正義の光で邪な魂を祓う勧善の戦乙女。\n多彩な支援効果で味方を支え、継続ダメージを与える聖浄\nの光が戦乙女の聖槍を喚び寄せ、悪をこらしめる。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/08/26 11:59:59", "しぇふぃ", 3, 2.09, 0, 0, 1, 0, 1, "シェフィ（ヴァードラッヘ）", 0, 0, 0, 0, 139801, 0, 139801, 386, 0, 139801, "2026/08/23 12:00:00", 139801, 450, "【物理】中衛で兄妹の絆と不撓の心で覚醒した氷竜少女。\n個も群も薙ぎ払うＵＢと、【氷竜超克】状態時に発生する\n追撃状態で敵を咬断し、大切な人と歩む未来を切り拓く。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/07/15 11:59:59", "るいずまりー", 3, 2.09, 0, 0, 1, 0, 2, "ルイズマリー（サマー）", 0, 55, 0, 0, 139901, 0, 139901, 757, 55, 139901, "2026/07/03 12:00:00", 139901, 450, "【魔法】後衛で、大人の階段を上りたい水着の錬金術師。\n発動回数で性能が上昇するＵＢとスキルで、調和状態の\n付与と攻防たゆまぬ支援を行い、ひと夏の思い出を創る。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/07/31 11:59:59", "くれじった", 3, 2.09, 0, 0, 1, 0, 2, "クレジッタ（サマー）", 0, 54, 0, 0, 140001, 0, 140001, 730, 54, 140001, "2026/07/15 12:00:00", 140001, 450, "【魔法】後衛で、リゾート建設に奔走する水着の女商人。\n初回発動時に強力な攻撃支援と一定時間魔攻・物防・魔防\nダウンを無効化するスキルで、豪奢に味方を駆り立てる。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/08/15 11:59:59", "ふぶき", 3, 2.09, 0, 0, 1, 0, 1, "フブキ（サマー）", 0, 54, 0, 0, 140101, 0, 140101, 376, 54, 140101, "2026/07/31 12:00:00", 140101, 450, "【物理】中衛であざとくラヴを奪う超天才びしょーじょ。\n毒と火傷で弱らせた敵をあざ笑うかのように、自分と\n先頭の味方へＴＰ回復や行動不能無効を付与し強化する。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "うぁんぴぃ", 3, 2.09, 0, 0, 0, 0, 2, "ヴァンピィ（サマー）", 0, 43, 0, 0, 140201, 0, 140201, 582, 43, 140201, "2026/08/15 12:00:00", 140201, 450, "【魔法】中衛でけんぞくとラヴを集めるつよつよ吸血姫。\nスキルでＴＰを吸収し、【チャームスローブ】を消費して\n放つＵＢは、ほとばしるカワいさで敵を骨抜きにする。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/08/26 11:59:59", "てぃあ", 3, 2.09, 0, 0, 1, 0, 2, "ティア", 0, 0, 0, 0, 140301, 0, 140301, 744, 0, 140301, "2026/08/23 12:00:00", 140301, 450, "【魔法】後衛から、中立で平等とうそぶく認識の修正者。\n敵の認識を乱して弱体効果を付与し、一方で味方が受ける\n混乱、誘惑状態を無効化しお気に入りの彼に肩入れする。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "しずる", 1, 0.0, 0, 0, 0, 0, 0, "シズル（ニューイヤー）", 0, 1, 0, 0, 0, 0, 141401, 0, 1, 141401, "2015/04/01 15:00:00", 0, 0, "");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "うぁいおれっと", 3, 0.0, 0, 0, 0, 0, 0, "ヴァイオレット（イサナミ）", 0, 1, 0, 0, 0, 0, 141501, 0, 0, 141501, "2015/04/01 15:00:00", 0, 0, "");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "ぐれいす", 3, 0.0, 0, 0, 1, 0, 0, "グレイス（バニー）", 0, 1, 0, 0, 0, 0, 141601, 0, 4, 141601, "2015/04/01 15:00:00", 0, 0, "");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "じーた", 3, 1.965, 4, 0, 0, 0, 1, "ジータ", 0, 34, 0, 0, 105701, 0, 170101, 245, 34, 170101, "2015/04/01 15:00:00", 170101, 450, "【物理】前衛で、先手必勝の大技を繰り出す騎空士。\nスキルによるＴＰ回復は、ユニオンバーストの発動を早め\nバトルの序盤から敵前衛に大ダメージを与える。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/08/26 11:59:59", "ひより", 3, 1.62, 7, 0, 1, 0, 1, "ヒヨリ（プリンセス）", 0, 0, 0, 0, 180101, 0, 180101, 199, 0, 180101, "2026/08/23 12:00:00", 180101, 450, "【物理】前衛で炎翼を背に敵を粉砕する、陽気な元気娘。\n戦いが続く程に自身の攻撃能力を強めるスキルを操り、\n高めた力で放つ超爆の一撃は、あらゆる敵を塵と化す。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/08/26 11:59:59", "ゆい", 3, 1.92, 1, 0, 1, 0, 2, "ユイ（プリンセス）", 0, 0, 0, 0, 180201, 0, 180201, 767, 0, 180201, "2026/08/23 12:00:00", 180201, 450, "【魔法】後衛から極大魔法で敵を滅する願いの魔法士。\nＴＰを回復しつつ攻撃力を累積アップする補助スキルで\n自身の力を高め、強力な範囲攻撃を放ち敵を一掃する。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/08/26 11:59:59", "れい", 3, 1.965, 7, 0, 1, 0, 1, "レイ（プリンセス）", 0, 0, 0, 0, 180301, 0, 180301, 377, 0, 180301, "2026/08/23 12:00:00", 180301, 450, "【物理】中衛で風刃を従え激戦を流麗に征く嵐翼の剣士。\n敵が多い程に効果が高まる自己強化スキルで、自身を奮い\n立たせ、強力な範囲攻撃スキルで一切の敵を鏖滅する。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/08/26 11:59:59", "ぺこりーぬ", 3, 1.965, 1, 0, 1, 0, 1, "ペコリーヌ（プリンセス）", 0, 0, 0, 0, 180401, 0, 180401, 155, 0, 180401, "2026/08/23 12:00:00", 180401, 450, "【物理】前衛で、攻防共に絶大な力を誇る腹ペコ王女。\nＨＰが多い時は爆発的な攻撃力で、いかなる敵をも屠り、\nＨＰが減ると自己回復能力を得て、鉄壁の護りを見せる。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/08/26 11:59:59", "こっころ", 3, 2.14, 1, 0, 1, 0, 1, "コッコロ（プリンセス）", 0, 0, 0, 0, 180501, 0, 180501, 555, 0, 180501, "2026/08/23 12:00:00", 180501, 450, "【物理】中衛で、絶大な補助スキルを繰出す純白の巫女。\n味方の攻撃力とクリティカルダメージを強化しつつ、\n二つの全体回復スキルで味方を堅固に守護し勝利へ導く。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/08/26 11:59:59", "きゃる", 3, 1.92, 1, 0, 1, 0, 2, "キャル（プリンセス）", 0, 0, 0, 0, 180601, 0, 180601, 747, 0, 180601, "2026/08/23 12:00:00", 180601, 450, "【魔法】後衛で、極大魔法を操り敵を討つ姫装の猫娘。\n回復や補助を兼ねた各攻撃スキルを駆使し戦況を整え、\n極大威力のユニオンバーストを撃ち込み敵を燼滅する。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/08/26 11:59:59", "はつねしおり", 3, 1.75, 1, 0, 1, 0, 1, "ハツネ＆シオリ", 0, 0, 0, 0, 180701, 0, 180701, 732, 0, 180701, "2026/08/23 12:00:00", 180701, 450, "【物理】後衛から、真の絆の力を発揮する仲良し姉妹。\n敵の数が増えるほど威力が高まる攻撃スキルと、周りの\n味方を強化するスキルを操り、立ち塞がる敵を一掃する。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/08/26 11:59:59", "みそぎみみきょうか", 3, 1.5, 1, 0, 1, 0, 1, "ミソギ＆ミミ＆キョウカ", 0, 0, 0, 0, 180801, 0, 180801, 465, 0, 180801, "2026/08/23 12:00:00", 180801, 450, "【物理】中衛で敵単体に必殺の一撃を放つ仲良しトリオ。\n３人の力を合わせて放つ攻撃は、相手の弱点に合わせて\n物理から魔法攻撃に変化し、どんな強い敵も退治する！");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/08/26 11:59:59", "あきのされん", 3, 2.09, 1, 0, 1, 0, 1, "アキノ＆サレン", 0, 0, 0, 0, 180901, 0, 180901, 421, 0, 180901, "2026/08/23 12:00:00", 180901, 450, "【物理】中衛で背を預けあう最高の好敵手で親友の二人。\n味方の物理攻撃をサポートしつつＨＰとＴＰを継続回復し\nＨＰが多いほど威力が増すＵＢで、共に勝利の道を征く。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/08/26 11:59:59", "あんぐれあ", 3, 2.09, 1, 0, 1, 0, 2, "アン＆グレア", 0, 0, 0, 0, 181001, 0, 181001, 577, 0, 181001, "2026/08/23 12:00:00", 181001, 450, "【魔法】中衛で、魔力共鳴し連撃を放つマナリアの双姫。\nステータスアップ効果を受けると増加する【友情の魔印】\nがスキルを強化し、波長を合わせた炎の魔槍で敵を討つ。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/08/26 11:59:59", "しずるりの", 3, 1.92, 1, 0, 1, 0, 1, "シズル＆リノ", 0, 0, 0, 0, 181101, 0, 181101, 551, 0, 181101, "2026/08/23 12:00:00", 181101, 450, "【物理】中衛でお揃い衣装の、真偽を超えた仲良し姉妹。\n攻守共に味方を支えるシズルと、クリティカル時に強力な\nダメージを与えるリノ、姉妹の絆で困難を跳ね除ける！");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2026/08/26 11:59:59", "しぇふぃ", 3, 1.92, 1, 0, 1, 0, 1, "シェフィ（プリンセス）", 0, 0, 0, 0, 181201, 0, 181201, 368, 0, 181201, "2026/08/23 12:00:00", 181201, 450, "【物理】中衛で新たな力と共に再廻する姫装の氷竜少女。\n環境効果【絶氷】でクリティカルダメージを高め、火力と\n手数を併せ持つ剣技で、再び共に歩むため道を切り開く。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "かりん", 1, 0.0, 0, 0, 0, 0, 1, "カリン", 0, 1, 0, 0, 0, 0, 190801, 0, 1, 190801, "2015/04/01 15:00:00", 0, 0, "");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "ぺてるぎうす", 1, 0.0, 0, 0, 0, 0, 1, "ペテルギウス", 0, 1, 0, 0, 0, 0, 191201, 0, 1, 191201, "2015/04/01 15:00:00", 0, 0, "");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "かずまさ", 1, 2.22, 0, 0, 1, 0, 1, "カズマサ", 0, 6, 0, 0, 191301, 0, 191301, 850, 6, 191301, "2015/04/01 15:00:00", 191301, 450, "【物理】皆から愛される漁師町のポンコツ漁師。\nユニオンバーストは強力なスタン効果を持つが、\n自身のＨＰが50%以下では尻もちをついてしまう。\n\n・通常攻撃とユニオンバーストを駆使して戦う。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "こっころ", 0, 0.0, 0, 0, 0, 0, 0, "コッコロ", 0, 6, 0, 0, 0, 0, 191401, 0, 6, 191401, "2015/04/01 15:00:00", 0, 0, "");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "しゅじんこう", 0, 0.0, 0, 0, 0, 0, 0, "主人公", 0, 0, 0, 0, 100101, 0, 191501, 1600, 0, 191501, "2015/04/01 15:00:00", 100101, 150, "残されたわずかな時間で宿題を終わらせんとする\nルーセント学院の生徒。楽しい夏休みの思い出を\n守るため、山積みの宿題へと立ち向かう。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "しゅじんこう", 0, 0.0, 0, 0, 0, 0, 0, "主人公", 0, 0, 0, 0, 100101, 0, 191601, 1600, 0, 191601, "2015/04/01 15:00:00", 100101, 150, "残されたわずかな時間で宿題を終わらせんとする\nルーセント学院の生徒。楽しい夏休みの思い出を\n守るため、山積みの宿題へと立ち向かう。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "しゅじんこう", 0, 0.0, 0, 0, 0, 0, 0, "主人公", 0, 0, 0, 0, 100101, 0, 191701, 1600, 0, 191701, "2015/04/01 15:00:00", 100101, 150, "残されたわずかな時間で宿題を終わらせんとする\nルーセント学院の生徒。楽しい夏休みの思い出を\n守るため、山積みの宿題へと立ち向かう。");
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (0, "2030/12/31 15:00:00", "しぇふぃ", 1, 1.92, 0, 0, 1, 0, 1, "シェフィ", 0, 0, 0, 0, 192701, 0, 192701, 855, 0, 192701, "2015/04/01 15:00:00", 192701, 450, "");
